  function commonsCombatImage(file){const raw=String(file||'').trim();if(!raw)return '';if(/^https?:\/\//i.test(raw))return normalizeCombatImageSource(raw);return COMBAT_COMMONS_DIRECT_FILES[raw]||`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(raw)}?width=1200`;}
  function normalizeCombatImageSource(url=''){const raw=cleanText(url);if(!raw)return '';const m=raw.match(/^https:\/\/commons\.wikimedia\.org\/wiki\/Special:(?:Redirect\/file|FilePath)\/([^?]+)/i);if(!m)return raw;let file='';try{file=decodeURIComponent(m[1]);}catch{file=m[1];}file=file.replace(/_/g,' ');return COMBAT_COMMONS_DIRECT_FILES[file]||`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}?width=1200`;}  const DEFAULT_OPPONENT_IMAGE_DATA='assets/img/default-opponent.png';

  function combatDisplayImageUrl(op={}){const tpl=typeof COMBAT_TEMPLATE_MAP!=='undefined'?COMBAT_TEMPLATE_MAP.get(cleanText(op?.templateId)):null,meta=(op&&Object.keys(op).length?op:tpl)||tpl;if(op?.aiIllustration||tpl?.aiIllustration)return combatOpponentImageUrl(op?.name||tpl?.name||'oponente',meta);const staticUrl=normalizeCombatImageSource(cleanText(op?.image)||cleanText(tpl?.image));return staticUrl||'';}
  function combatImageFallbackData(name='Oponente'){return DEFAULT_OPPONENT_IMAGE_DATA;}
  function installCombatImageFallback(img,name='',finalFailure=null){if(!img)return;const desired=cleanText(img.dataset.combatDesiredSrc||img.currentSrc||img.src),fallback=combatImageFallbackData(name);img.dataset.combatDesiredSrc=desired;let settled=false,timer=null;const clear=()=>{if(timer){clearTimeout(timer);timer=null;}};const keepFallback=()=>{if(settled)return;settled=true;clear();img.dataset.combatFallbackStage='2';img.src=fallback;img.classList.remove('hidden');if(typeof finalFailure==='function')finalFailure();};img.onerror=keepFallback;if(!desired||desired===fallback){keepFallback();return;}if(/^data:image\//i.test(desired)){img.src=desired;return;}img.dataset.combatFallbackStage='1';img.src=fallback;const probe=new Image();probe.onload=()=>{if(settled)return;settled=true;clear();img.dataset.combatFallbackStage='0';img.onerror=keepFallback;img.src=desired;};probe.onerror=keepFallback;timer=setTimeout(keepFallback,7000);probe.src=desired;}

