  function normalizeCombatResistance(r={}){const item=cleanText(r.item),mode=String(r.mode||'IMMUNE').toUpperCase()==='REDUCE'?'REDUCE':'IMMUNE',value=Math.max(0,parseInt(r.value)||0);return item?{id:cleanText(r.id)||combatUid('res'),item,mode,value}:null;}
  function normalizeCombatContextAction(a={}){const test=['NONE','APTIDAO','FORTUNA','SANIDADE'].includes(String(a.test||'NONE').toUpperCase())?String(a.test||'NONE').toUpperCase():'NONE',result=['CONTINUE','DEFEAT','FLEE','RELEASE','PREVENT_REBIRTH'].includes(String(a.result||'CONTINUE').toUpperCase())?String(a.result||'CONTINUE').toUpperCase():'CONTINUE',availability=['ACTIVE','DEFEATED','ANY'].includes(String(a.availability||'ACTIVE').toUpperCase())?String(a.availability||'ACTIVE').toUpperCase():'ACTIVE';return {id:cleanText(a.id)||combatUid('act'),name:cleanText(a.name)||'Ação especial',requiredItem:cleanText(a.requiredItem),consume:!!a.consume,test,testMod:Math.max(-9,Math.min(9,parseInt(a.testMod)||0)),damageExpr:cleanText(a.damageExpr),fx:cleanText(a.fx),fxTarget:a.fxTarget==='HERO'?'HERO':'OPPONENT',message:cleanText(a.message),result,availability};}
  const COMBAT_ANTIDOTE_LOOT='!Antídoto|!{Estado:Envenenado}';
  function combatLootWithRequiredAntidote(raw='',specialties=[]){
    const entries=String(raw||'').split(/[;\n]+/).map(x=>x.trim()).filter(Boolean);
    if(!(specialties||[]).includes('VENENO'))return entries.join('; ');
    const fold=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
    const hasAntidote=entries.some(spec=>{const qty=spec.match(/^(?:\d+|\d*d\d+(?:[+-]\d+)?)\s+(.+)$/i),item=qty?qty[1]:spec;return fold(itemMeta(item).name)==='antidoto';});
    if(!hasAntidote)entries.push(COMBAT_ANTIDOTE_LOOT);
    return entries.join('; ');
  }
