  function npcTreasureAcquisitionLabel(npc=npcSocialDefinition()){
    const raw=String(npc?.treasure||'').trim();if(!raw)return 'uma concessão';
    const parts=raw.split(/[;\n]+/).map(cleanText).filter(Boolean).map(fx=>{
      if(/^TESOURO$/i.test(fx))return 'um tesouro';
      const state=fx.match(/^ESTADO\s*:\s*(.+)$/i);if(state)return `“${cleanStateName(state[1])||cleanText(state[1])}”`;
      const gain=fx.match(/^\+\s*(\d+)\s+(.+)$/i);if(gain)return `${gain[1]} ${cleanText(gain[2])}`;
      return fx.replace(/^\+\s*/,'');
    });
    if(!parts.length)return 'uma concessão';if(parts.length===1)return parts[0];if(parts.length===2)return `${parts[0]} e ${parts[1]}`;return `${parts.slice(0,-1).join(', ')} e ${parts.at(-1)}`;
  }
  function npcOfferPreviewLabel(npc=npcSocialDefinition()){
    const explicit=cleanText(npc?.offerHint);if(explicit)return explicit;
    const raw=String(npc?.treasure||'').trim();if(!raw)return 'Uma possível concessão';
    const first=raw.split(/[;\n]+/).map(cleanText).filter(Boolean)[0]||'';
    if(/^TESOURO$/i.test(first))return 'Algo de valor';
    const state=first.match(/^ESTADO\s*:\s*(.+)$/i);if(state){const label=cleanStateName(state[1])||cleanText(state[1]);if(/rumor|mexeric|segredo|senha|inform|conhec|pista/i.test(label))return `Informação: ${label}`;if(/passagem|autoriza|acesso|audiência|audiencia|permiss/i.test(label))return `Acesso: ${label}`;if(/bênção|bencao|benção/i.test(label))return `Bênção: ${label}`;return `Favor: ${label}`;}
    const gain=first.match(/^\+\s*(\d+)\s+(.+)$/i);if(gain){const qty=Math.max(1,Number(gain[1])||1),item=cleanText(gain[2]);return qty===1?item:`${qty} ${item}`;}
    return first.replace(/^\+\s*/,'')||'Uma possível concessão';
  }
  function npcTreasureAcquisitionSentence(npc=npcSocialDefinition()){const name=cleanText(npc?.name||'NPC')||'NPC';return `Você adquiriu ${npcTreasureAcquisitionLabel(npc)} de ${name}.`;}
