  async function applyChoiceEffectRawList(c,raws,{phase='always',source='💱',branch=null}={}){if(!raws.length)return;const scope=choiceFxScope(c,phase,branch);if(scope.kind==='NEXT_COMBAT'){ensureNextCombatEffects().push(...raws);toast('Efeito preparado até o fim do próximo combate.');return;}if(scope.kind==='NEXT_TEST'){if(phase==='always'&&c?.type==='test'){c.__currentTestFxReverts=(c.__currentTestFxReverts||[]).concat(scopedEffectRecords(raws,source));}else{ensureNextTestEffects().push(...raws);toast('Efeito preparado até o fim do próximo teste.');}return;}if(scope.kind==='SECTION'){c.__sectionFxReverts=(c.__sectionFxReverts||[]).concat(scopedEffectRecords(raws,source));return;}if(scope.kind==='TURNS'||scope.kind==='HOURS'){const records=scopedEffectRecords(raws,source);if(records.length){const p=ensureTimeState(),minutes=scope.kind==='TURNS'?scope.value*30:scope.value*60;ensureTimedChoiceEffects().push({expiresAtMinutes:(Number(p?.gameMinutes)||0)+minutes,records});}return;}for(const fx of raws)await applyCompactEffect(fx,{source});}
